python3 -c '
import math

# Conditioning on N_real opens, each open is after_hours w.p. 0.3 (mole) vs 0.1 (innocent).
# Plus for innocent non-decoy, fake_ah ~ Pois(lambda_frame), where over 3 days lambda_frame = 3 * (1.0 / 38) = 0.07895.
# If an employee has personal open rate r_i (drawn identically for mole and innocent since log_rate_mole == log_rate_benign == 1!),
# then for mole: real_opens = dt + ah, and P(ah | total=n, mole) = Binom(ah; n, 0.3) * P(total=n | r_i).
# For innocent: total = real_opens + fake_ah. Since fake_ah is tiny (~0.079 over 3 days):
# Let us integrate r_i ~ Gamma(shape=1, scale=1) or empirical! Wait: if r_i == 1 fixed, Pois(10; 3) = 0.0008, which is ~1 in 1250 (across 40 employees, 40 * 0.0008 = 3.2% chance, or Gamma noise!).
# Either way, since log_rate_mole == log_rate_benign == 1.0, total real opens gives ZERO information between mole and innocent EXCEPT that fake_ah adds ~0.026/day to innocent!

def pois(k, lam):
    return (lam ** k) * math.exp(-lam) / math.factorial(k)

def binom(k, n, p):
    if k < 0 or k > n: return 0.0
    return math.comb(n, k) * (p ** k) * ((1 - p) ** (n - k))

# Exact likelihood integrating over r_i ~ Gamma(a, a) (say a=2, mean 1) over D=3 days:
# P(dt, ah | r) = Pois(dt; D*0.7*r) * Pois(ah; D*0.3*r) for mole
# P(dt, ah | r) = Pois(dt; D*0.9*r) * Pois(ah; D*0.1*r + D*0.0263) for innocent non-decoy
def marg_prob(dt, ah, is_mole, D=3, a=2.0):
    # Numerical integration over r
    total = 0.0
    steps = 400
    rmax = 8.0
    dr = rmax / steps
    for i in range(1, steps + 1):
        r = (i - 0.5) * dr
        prior_r = ((a ** a) / math.gamma(a)) * (r ** (a - 1)) * math.exp(-a * r)
        if is_mole:
            p = pois(dt, D * 0.7 * r) * pois(ah, D * 0.3 * r)
        else:
            p = pois(dt, D * 0.9 * r) * pois(ah, D * 0.1 * r + D * (1.0 / 38.0))
        total += prior_r * p * dr
    return total

employees = {
    "e01": ("Finance", 3), "e05": ("Finance", 3), "e12": ("Finance", 3), "e13": ("Finance", 1),
    "e21": ("Finance", 3), "e27": ("Finance", 1), "e39": ("Finance", 2),
    "e03": ("Legal", 3), "e07": ("Legal", 1), "e11": ("Legal", 3), "e17": ("Legal", 1), "e25": ("Legal", 3)
}
logs = {
    "e01": (3, 1), "e05": (1, 0), "e12": (3, 1), "e13": (1, 1), "e21": (2, 0), "e27": (3, 0), "e39": (4, 0),
    "e03": (10, 0), "e07": (2, 1), "e11": (1, 1), "e17": (1, 0), "e25": (3, 0)
}
interviews = {
    "e01": [False], "e03": [False], "e05": [False], "e07": [False],
    "e11": [False], "e12": [False], "e13": [True]
}

scores = {}
for s, (dept, cl) in employees.items():
    p_leak = 0.27625 if dept == "Finance" else 0.07759375
    dt, ah = logs[s]
    lr_log = marg_prob(dt, ah, True) / marg_prob(dt, ah, False)
    lr_int = 1.0
    for ev in interviews.get(s, []):
        lr_int *= (1.2 if ev else 0.95)
    scores[s] = p_leak * lr_log * lr_int

tot = sum(scores.values())
for s in sorted(employees, key=lambda x: -scores[x]):
    print(f"{s} ({employees[s][0]:7s}): P={scores[s]/tot:.4f}  logs={logs[s]}  int={interviews.get(s, [])}")
'

