import math, itertools

fin = ["e01", "e05", "e12", "e13", "e21", "e27", "e39"]
probs = {"e13":0.3579, "e01":0.1714, "e05":0.1193, "e21":0.1193, "e12":0.1037, "e39":0.0722, "e27":0.0561}
c4   = {"e13":"A", "e21":"A", "e01":"B", "e05":"B", "e27":"B", "e12":"C", "e39":"C"}
c4_2 = {"e13":"A", "e21":"C", "e01":"B", "e05":"C", "e27":"A", "e12":"C", "e39":"B"}

labels = ["A", "B", "C"]
valid_cols = [col for col in itertools.product(labels, repeat=7) if all(1 <= col.count(L) <= 3 for L in labels)]

best = None
for col5 in valid_cols:
    m5 = dict(zip(fin, col5))
    if len({(c4[s], m5[s]) for s in fin}) < 7: continue
    if len({(c4_2[s], m5[s]) for s in fin}) < 7: continue
    for col52 in valid_cols:
        m52 = dict(zip(fin, col52))
        if len({(c4[s], m52[s]) for s in fin}) < 7: continue
        if len({(c4_2[s], m52[s]) for s in fin}) < 7: continue
        if len({(m5[s], m52[s]) for s in fin}) < 7: continue
        ent = 0.0
        for m in (m5, m52):
            for L in labels:
                pL = sum(probs[s] for s in fin if m[s] == L)
                if pL > 0: ent -= pL * math.log(pL)
        if best is None or ent > best[0]:
            best = (ent, m5, m52)

ent, m5, m52 = best
print("Entropy sum:", round(ent, 4))
for s in sorted(fin, key=lambda x: -probs[x]):
    print(f"  {s} (P={probs[s]:.3f}): c4={c4[s]} c4-2={c4_2[s]} c5={m5[s]} c5-2={m52[s]}")
'

